/*
  Starter product catalogue (121 products), so a brand-new database
  isn't an empty shop. Exported from the working local database after
  migrations 001–004, so categories are the current ones (headwear, tops…).

  GUARDED: only inserts when the products table is EMPTY. On a database that
  already has products — local, or production after the first deploy — this
  does nothing, so it can never duplicate or overwrite your catalogue.

  Contains products only. No users, emails, passwords or activity.
*/

BEGIN;

DO $seed$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM products) THEN

    -- Ids were inserted explicitly, so move the counter past them or the next
    -- product added by hand would collide with an existing id.
    PERFORM setval(pg_get_serial_sequence('products', 'id'), (SELECT max(id) FROM products));
  END IF;
END
$seed$;

COMMIT;
